from __future__ import annotations

import os
from html import escape

from app.platform.auth.service import build_auth_summary
from app.platform.ci_repair.service import build_ci_repair_summary
from app.platform.founder_console.service import build_founder_console_summary
from app.platform.github_execution.service import build_github_execution_summary
from app.platform.mission_control.service import build_mission_control_summary
from app.platform.operating_console.service import build_operating_console_summary
from app.platform.pr_orchestration.service import build_pr_orchestration_summary


def render_founder_experience() -> str:
    mc = build_mission_control_summary()
    console = build_founder_console_summary()
    operating = build_operating_console_summary()
    auth = build_auth_summary()
    github = build_github_execution_summary()
    ci = build_ci_repair_summary()
    prs = build_pr_orchestration_summary()
    founder_email = escape(os.getenv("FOUNDER_EMAIL", "founder@ai-software-factory.local"))
    ai_status = escape(f"{console['runtime']['ai_provider']} · {console['runtime']['model']}")
    github_status = escape(str(github.get("status", "unknown")))
    env = escape(str(getattr(mc, "environment", "production")))
    region = escape(str(getattr(mc, "region", "asia-southeast1")))
    return f"""
<!doctype html>
<html lang='en'>
<head>
<meta charset='utf-8'/><meta name='viewport' content='width=device-width,initial-scale=1'/><title>AI Software Factory · Mission Control</title>
<style>
:root{{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color-scheme:dark;--bg:#07111f;--panel:#0d1728;--line:#22314d;--text:#f2f7ff;--muted:#9aa9c2;--blue:#3b82f6;--purple:#8b5cf6;--green:#22c55e;--orange:#f97316;--red:#ef4444}}*{{box-sizing:border-box}}body{{margin:0;min-height:100vh;background:radial-gradient(circle at 18% 0,#122a55 0,#07111f 36%,#030712 100%);color:var(--text)}}button,input,textarea{{font:inherit}}button,a{{cursor:pointer}}a{{color:inherit;text-decoration:none}}.login-screen{{min-height:100vh;display:grid;place-items:center;padding:28px}}.login-card{{width:min(480px,100%);border:1px solid var(--line);background:rgba(8,15,29,.96);border-radius:26px;padding:30px;box-shadow:0 30px 90px rgba(0,0,0,.4)}}.login-card h1{{margin:10px 0 8px;font-size:34px}}.brand-small{{font-size:12px;letter-spacing:.18em;color:var(--muted);text-transform:uppercase}}label{{display:block;color:var(--muted);font-size:13px;margin:14px 0 6px}}input,textarea{{width:100%;border:1px solid var(--line);background:#07101e;color:var(--text);border-radius:13px;padding:13px;outline:0}}.primary,.login-card button{{border:0;border-radius:13px;padding:13px 17px;background:linear-gradient(135deg,var(--blue),var(--purple));color:white;font-weight:800}}.login-card button{{width:100%;margin-top:14px}}.muted,.small{{color:var(--muted)}}.small{{font-size:12px}}.error{{color:#ff9b9b;margin-top:12px;min-height:22px}}
.app{{display:none;min-height:100vh;grid-template-columns:280px 1fr}}aside{{position:sticky;top:0;height:100vh;padding:20px 16px;border-right:1px solid var(--line);background:rgba(4,12,24,.86);overflow:auto}}main{{padding:22px;min-width:0}}.logo{{display:flex;gap:12px;align-items:center;margin-bottom:20px}}.mark{{width:40px;height:40px;border-radius:12px;background:linear-gradient(135deg,#6366f1,#60a5fa);display:grid;place-items:center;font-weight:900}}.logo strong{{display:block;font-size:18px}}.logo span{{color:#60a5fa;font-size:12px;text-transform:uppercase;letter-spacing:.08em}}.nav a{{display:flex;gap:10px;align-items:center;padding:11px 12px;border-radius:10px;color:#c7d2e7;margin:3px 0}}.nav a:hover,.nav a.active{{background:linear-gradient(90deg,#1e40af,#6d28d9);color:white}}.nav-badge{{margin-left:auto;background:#7c3aed;border-radius:999px;padding:2px 8px;font-size:11px}}.logout,.secondary{{border:1px solid var(--line);background:#13233d;color:#dbeafe;border-radius:10px;padding:10px 13px;font-weight:800}}.sidebar-footer{{margin-top:18px;border-top:1px solid var(--line);padding-top:14px}}.sidebar-footer .logout{{width:100%}}.topbar{{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:18px}}.top-actions{{display:flex;gap:10px;align-items:center}}.user-pill{{display:flex;align-items:center;gap:10px;border:1px solid var(--line);background:rgba(15,27,49,.72);border-radius:999px;padding:8px 12px}}.avatar{{width:32px;height:32px;border-radius:50%;background:linear-gradient(135deg,#f59e0b,#fef3c7);display:grid;place-items:center;color:#111827;font-weight:900}}
.card{{border:1px solid var(--line);background:linear-gradient(180deg,rgba(15,27,49,.88),rgba(8,15,29,.82));border-radius:15px;padding:16px;box-shadow:0 24px 70px rgba(0,0,0,.13)}}.greeting h1{{font-size:30px;margin:0 0 6px}}.command{{margin-top:14px;display:grid;grid-template-columns:1fr 56px;gap:10px;border:1px solid #6d28d9;background:#07101e;border-radius:13px;padding:8px}}.command input{{border:0;background:transparent;font-size:17px}}.command button{{border:0;border-radius:10px;background:linear-gradient(135deg,var(--purple),var(--blue));color:white;font-size:24px}}.chips{{display:flex;gap:9px;flex-wrap:wrap;margin-top:12px}}.chip{{border:1px solid var(--line);background:rgba(15,27,49,.72);border-radius:999px;padding:8px 12px;color:#dbeafe;font-size:13px}}.grid{{display:grid;gap:14px}}.kpis{{grid-template-columns:repeat(5,minmax(0,1fr));margin:14px 0}}.kpi-title{{font-size:12px;color:#bdc7d9}}.kpi-value{{font-size:27px;font-weight:900;margin:8px 0 4px}}.up{{color:var(--green);font-weight:800}}.section{{display:none}}.section.active{{display:block}}.layout{{display:grid;grid-template-columns:minmax(0,1fr) 420px;gap:14px}}.left-col,.right-col{{display:grid;gap:14px}}.section-head{{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}}.section-head h2{{font-size:16px;margin:0;text-transform:uppercase}}table{{width:100%;border-collapse:collapse}}th,td{{text-align:left;border-bottom:1px solid rgba(255,255,255,.07);padding:11px 8px;font-size:13px}}th{{color:var(--muted)}}.tag{{display:inline-flex;border-radius:7px;padding:4px 9px;font-size:12px;font-weight:800;background:#12315e;color:#93c5fd}}.tag.orange{{background:#3a230e;color:#fb923c}}.tag.purple{{background:#2b174d;color:#d8b4fe}}.bar{{width:86px;height:6px;border-radius:999px;background:#1e2d47;overflow:hidden}}.bar i{{display:block;height:100%;background:linear-gradient(90deg,var(--blue),#818cf8)}}.pipeline{{display:flex;align-items:center;justify-content:space-between;gap:8px;overflow:auto}}.stage{{text-align:center;min-width:82px}}.stage-icon{{width:45px;height:45px;border-radius:12px;background:#102846;border:1px solid #24405f;display:grid;place-items:center;margin:0 auto 8px;font-size:20px;position:relative}}.count{{position:absolute;right:-8px;top:-8px;background:#1d4ed8;border-radius:999px;padding:2px 7px;font-size:11px}}.decision,.activity,.row{{display:grid;gap:12px;align-items:center;border-top:1px solid rgba(255,255,255,.07);padding:12px 0}}.decision{{grid-template-columns:44px 1fr auto auto}}.activity{{grid-template-columns:64px 1fr auto}}.row{{grid-template-columns:44px 1fr auto}}.bottom,.panel-grid{{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:14px}}.endpoint{{display:inline-block;background:#07101e;border:1px solid var(--line);border-radius:8px;padding:5px 8px;color:#93c5fd;font-size:12px;margin-top:8px}}.modal{{display:none;position:fixed;inset:0;background:rgba(0,0,0,.55);backdrop-filter:blur(8px);z-index:10;place-items:center;padding:24px}}.modal.active{{display:grid}}.modal-card{{width:min(880px,100%);max-height:82vh;overflow:auto;border:1px solid var(--line);background:#08111f;border-radius:18px;padding:18px}}textarea{{min-height:180px;line-height:1.45}}pre{{white-space:pre-wrap;background:#050b15;border:1px solid var(--line);border-radius:12px;padding:14px;color:#dbeafe;line-height:1.45}}@media(max-width:1100px){{.app{{grid-template-columns:1fr}}aside{{position:relative;height:auto}}.kpis,.layout,.bottom,.panel-grid{{grid-template-columns:1fr}}}}
</style>
</head>
<body>
<section id='loginScreen' class='login-screen'><div class='login-card'><div class='brand-small'>AI Software Factory</div><h1>Platform Admin Login</h1><p class='muted'>Sign in to enter Mission Control.</p><label>Founder email</label><input id='email' value='{founder_email}' autocomplete='username'/><label>Password</label><input id='password' type='password' placeholder='FOUNDER_PASSWORD' autocomplete='current-password'/><button id='loginBtn' type='button'>Enter Mission Control</button><div id='loginError' class='error'></div><p class='muted'>Auth status: {escape(str(auth.get('status', 'unknown')))}</p></div></section>
<section id='app' class='app'><aside><div class='logo'><div class='mark'>AI</div><div><strong>AI Software Factory</strong><span>Mission Control</span></div></div><nav class='nav'><a class='active' data-section='home'>⌂ Home</a><a data-section='board'>▣ Board Room</a><a data-section='projects'>▤ Projects</a><a data-section='workflows'>⌘ Workflows</a><a data-section='proposals'>⇄ Proposals <span class='nav-badge'>3</span></a><a data-section='executions'>▧ Executions</a><a data-section='deployments'>◇ Deployments</a><a data-section='integrations'>◎ Integrations</a><a data-section='agents'>◌ Agents</a><a data-section='customers'>♙ Customers</a><a data-section='analytics'>↗ Analytics</a><a data-section='reports'>▥ Reports</a><a data-section='knowledge'>▱ Knowledge</a><a data-section='settings'>⚙ Settings</a></nav><div class='sidebar-footer'><button class='logout' onclick='logout()'>Logout</button></div></aside><main><div class='topbar'><div><div class='brand-small'>{env} · {region}</div><h1 style='margin:4px 0 0'>Founder Experience</h1></div><div class='top-actions'><button class='primary' onclick='openBoardRoom()'>♙ Board Room</button><div class='user-pill'><div class='avatar'>TT</div><div><strong>Toni Teh</strong><div class='small'>Founder</div></div></div><button class='logout' onclick='logout()'>Logout</button></div></div>
<section id='home' class='section active'><div class='card greeting'><h1>Good evening, Toni 👋</h1><p class='muted'>Everything looks great. What do you want the company to build, sell, fix, or improve today?</p><div class='command'><input id='commandInput' placeholder='Ask Mission Control to build, audit, sell, analyze, or deploy...'/><button onclick='startCommand()'>→</button></div><div class='chips'><span class='chip'>Launch new product</span><span class='chip'>Improve onboarding</span><span class='chip'>Review approvals</span><span class='chip'>Check company health</span></div></div><section class='grid kpis'>{_kpis()}</section><div class='layout'><div class='left-col'><div class='card'>{_projects()}</div><div class='card'>{_workflow()}</div></div><div class='right-col'><div class='card'>{_activity()}</div><div class='card'>{_approvals()}</div></div></div><div class='bottom'>{_customers()}{_products()}{_recommendations()}</div></section>
<section id='board' class='section'><div class='card'><div class='section-head'><h2>Board Room</h2><button class='primary' onclick='openBoardRoom()'>Start Discussion</button></div><p class='muted'>Ask AI CEO, CTO, Product, Engineering, QA, DevOps, and Security to discuss a company topic before work begins.</p><span class='endpoint'>POST /mission-control/operating-console/chat</span></div></section>
<section id='projects' class='section'><div class='card'>{_projects()}</div></section><section id='workflows' class='section'><div class='card'>{_workflow()}</div></section><section id='proposals' class='section'><div class='card'>{_approvals()}<span class='endpoint'>GET /mission-control/approvals</span></div></section><section id='executions' class='section'><div class='panel-grid'>{_panel('GitHub Executor', github_status, '/mission-control/github-executor')}{_panel('Code Generation','proposal-only', '/mission-control/code')}{_panel('CI Repair', escape(str(ci.get('status','unknown'))), '/mission-control/ci-repair')}</div></section><section id='deployments' class='section'><div class='panel-grid'>{_panel('Cloud Run','production', '/ready')}{_panel('Pull Requests', escape(str(prs.get('status','unknown'))), '/mission-control/pull-requests')}{_panel('Runtime', ai_status, '/mission-control/runtime')}</div></section><section id='integrations' class='section'><div class='panel-grid'>{_panel('GitHub', github_status, '/mission-control/github-executor')}{_panel('OpenAI Runtime', ai_status, '/mission-control/runtime/ai-provider')}{_panel('Google Cloud Run','production', '/ready')}</div></section><section id='agents' class='section'><div class='panel-grid'>{_agent('AI CEO','Strategy and company direction')}{_agent('AI CTO','Architecture and technical leadership')}{_agent('Product Manager','Roadmap and requirements')}{_agent('Engineering Manager','Execution planning')}{_agent('QA Lead','Validation and testing')}{_agent('DevOps Lead','Deployment and reliability')}</div></section><section id='customers' class='section'><div class='bottom'>{_customers()}{_products()}{_recommendations()}</div></section><section id='analytics' class='section'><section class='grid kpis'>{_kpis()}</section></section><section id='reports' class='section'><div class='panel-grid'>{_report('Daily CEO Brief')}{_report('Engineering Report')}{_report('Sales Report')}</div></section><section id='knowledge' class='section'><div class='panel-grid'>{_panel('Knowledge Vault','ready','/mission-control/knowledge-vault')}{_panel('Company Brain','ready','/mission-control/company-brain')}{_panel('Repository Intelligence','ready','/mission-control/repository')}</div></section><section id='settings' class='section'><div class='panel-grid'>{_panel('Founder Login', escape(str(auth.get('status','unknown'))), '/mission-control/auth')}{_panel('Environment', f'{env} · {region}', '/mission-control')}{_panel('Operating Console', escape(str(operating.get('status','ready'))), '/mission-control/operating-console')}</div></section></main></section>
<div id='boardModal' class='modal'><div class='modal-card'><div class='section-head'><h2>Board Room Discussion</h2><button class='secondary' onclick='closeBoardRoom()'>Close</button></div><textarea id='message' placeholder='Tell the Board Room what you want to discuss.'></textarea><p><button id='boardBtn' class='primary' onclick='boardRoomChat()'>Start Board Room Discussion</button> <button class='secondary' onclick='createWorkflow()'>Create Proposal From Discussion</button></p><h3>Board Room Response</h3><pre id='result'>Type a message and start the discussion.</pre></div></div>
<script>
window.addEventListener('DOMContentLoaded', function () {{
let token=localStorage.getItem('mission_control_token')||'';const loginScreen=document.getElementById('loginScreen');const app=document.getElementById('app');const result=document.getElementById('result');const loginError=document.getElementById('loginError');const loginBtn=document.getElementById('loginBtn');
function show(data){{if(result)result.textContent=typeof data==='string'?data:JSON.stringify(data,null,2);}}
function showBoard(data){{if(data.board_room_response){{show(data.board_room_response+'\n\n---\nMeeting ID: '+data.meeting_id+'\nStatus: '+data.status);}}else if(data.ai_response&&data.ai_response.output_text){{show(data.ai_response.output_text);}}else{{show(data);}}}}
function showApp(){{loginScreen.style.display='none';app.style.display='grid';}}
function showLogin(){{loginScreen.style.display='grid';app.style.display='none';}}
async function post(url,body){{const response=await fetch(url,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(body)}});return await response.json();}}
window.login=async function(){{loginError.textContent='';loginBtn.disabled=true;loginBtn.textContent='Signing in...';try{{const data=await post('/mission-control/auth/login',{{email:document.getElementById('email').value,password:document.getElementById('password').value}});if(data.session&&data.session.token){{token=data.session.token;localStorage.setItem('mission_control_token',token);showApp();}}else{{loginError.textContent=data.status||data.error||'Login failed';}}}}catch(error){{loginError.textContent='Login request failed: '+error;}}finally{{loginBtn.disabled=false;loginBtn.textContent='Enter Mission Control';}}}};
loginBtn.addEventListener('click',window.login);
window.validateSession=async function(){{if(!token){{showLogin();return;}}const data=await post('/mission-control/auth/session',{{token}});if(data.authenticated){{showApp();}}else{{localStorage.removeItem('mission_control_token');token='';showLogin();}}}};
window.logout=function(){{token='';localStorage.removeItem('mission_control_token');showLogin();}};
window.showSection=function(name){{document.querySelectorAll('.section').forEach(s=>s.classList.remove('active'));document.querySelectorAll('.nav a').forEach(a=>a.classList.remove('active'));const section=document.getElementById(name);if(section)section.classList.add('active');const nav=document.querySelector(".nav a[data-section='"+name+"']");if(nav)nav.classList.add('active');window.scrollTo(0,0);}};
document.querySelectorAll('.nav a[data-section]').forEach(a=>a.addEventListener('click',function(){{showSection(this.dataset.section);}}));
window.openBoardRoom=function(){{document.getElementById('boardModal').classList.add('active');}};window.closeBoardRoom=function(){{document.getElementById('boardModal').classList.remove('active');}};window.startCommand=function(){{document.getElementById('message').value=document.getElementById('commandInput').value||'';openBoardRoom();}};
window.boardRoomChat=async function(){{const btn=document.getElementById('boardBtn');btn.disabled=true;show('Board Room is thinking...');try{{const data=await post('/mission-control/operating-console/chat',{{token,message:document.getElementById('message').value}});showBoard(data);}}catch(error){{show('Board Room request failed: '+error);}}finally{{btn.disabled=false;}}}};
window.createWorkflow=async function(){{show('Creating proposal from Board Room discussion...');const data=await post('/mission-control/operating-console/workflow',{{token,action:'create-proposal',message:document.getElementById('message').value}});show(data);}};
validateSession();
}});
</script></body></html>
"""


